// =====================================================
// LED FUNCTIONS
// =====================================================

void showSolid() {

  if (!ledsOn) {

    strip.clear();
    strip.show();

    return;
  }

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );
  }

  strip.show();
}


void setSolid(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentEffect = SOLID;

  currentR = r;
  currentG = g;
  currentB = b;

  ledsOn = true;

  showSolid();
}


// =====================================================
// EFFECTS
// =====================================================

void updateEffects() {

  if (!ledsOn) return;


  // RAINBOW

  if (currentEffect == RAINBOW) {

    if (
      millis() - lastEffectUpdate >= 25
    ) {

      lastEffectUpdate = millis();

      for (int i = 0; i < LED_COUNT; i++) {

        uint32_t hue =
          effectStep +
          (i * 65536L / LED_COUNT);

        strip.setPixelColor(
          i,
          strip.gamma32(
            strip.ColorHSV(hue)
          )
        );
      }

      strip.show();

      effectStep += 500;

      if (effectStep >= 65536) {
        effectStep = 0;
      }
    }
  }


  // PURPLE / WHITE CHASE

  else if (
    currentEffect ==
    PURPLE_WHITE_CHASE
  ) {

    if (
      millis() - lastEffectUpdate >= 100
    ) {

      lastEffectUpdate = millis();

      for (int i = 0; i < LED_COUNT; i++) {

        if (
          ((i + effectStep) % 6) < 3
        ) {

          strip.setPixelColor(
            i,
            strip.Color(
              128,
              0,
              255
            )
          );

        } else {

          strip.setPixelColor(
            i,
            strip.Color(
              255,
              255,
              255
            )
          );
        }
      }

      strip.show();

      effectStep++;

      if (effectStep >= 6) {
        effectStep = 0;
      }
    }
  }
}


// =====================================================
// WEB ROUTES
// =====================================================

void setupWebServer() {

  server.on("/", HTTP_GET, []() {

    server.send(
      200,
      "text/html",
      controlPage
    );
  });


  server.on("/on", HTTP_GET, []() {

    ledsOn = true;

    if (currentEffect == SOLID) {
      showSolid();
    }

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/off", HTTP_GET, []() {

    ledsOn = false;

    strip.clear();
    strip.show();

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/purple", HTTP_GET, []() {

    setSolid(
      128,
      0,
      255
    );

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/white", HTTP_GET, []() {

    setSolid(
      255,
      255,
      255
    );

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/red", HTTP_GET, []() {

    setSolid(
      255,
      0,
      0
    );

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/green", HTTP_GET, []() {

    setSolid(
      0,
      255,
      0
    );

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/blue", HTTP_GET, []() {

    setSolid(
      0,
      0,
      255
    );

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/rainbow", HTTP_GET, []() {

    ledsOn = true;

    currentEffect = RAINBOW;
    effectStep = 0;

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on("/chase", HTTP_GET, []() {

    ledsOn = true;

    currentEffect =
      PURPLE_WHITE_CHASE;

    effectStep = 0;

    server.sendHeader(
      "Location",
      "/"
    );

    server.send(
      303,
      "text/plain",
      ""
    );
  });


  server.on(
    "/brightness",
    HTTP_GET,
    []() {

      if (server.hasArg("value")) {

        brightness =
          constrain(
            server
            .arg("value")
            .toInt(),
            0,
            255
          );

        strip.setBrightness(
          brightness
        );

        if (
          currentEffect ==
          SOLID
        ) {

          showSolid();
        }
      }

      server.send(
        200,
        "text/plain",
        "OK"
      );
    }
  );


  server.on(
    "/color",
    HTTP_GET,
    []() {

      if (
        server.hasArg("r") &&
        server.hasArg("g") &&
        server.hasArg("b")
      ) {

        setSolid(

          server
          .arg("r")
          .toInt(),

          server
          .arg("g")
          .toInt(),

          server
          .arg("b")
          .toInt()

        );
      }

      server.sendHeader(
        "Location",
        "/"
      );

      server.send(
        303,
        "text/plain",
        ""
      );
    }
  );


  // OTA PAGE

  server.on(
    "/updatepage",
    HTTP_GET,
    []() {

      server.send(
        200,
        "text/html",
        updatePage
      );
    }
  );


  // OTA UPLOAD

  server.on(

    "/update",

    HTTP_POST,

    []() {

      bool success =
        !Update.hasError();

      server.send(
        success ? 200 : 500,
        "text/plain",
        success
          ? "UPDATE SUCCESSFUL - REBOOTING"
          : "UPDATE FAILED"
      );

      delay(1000);

      if (success) {
        ESP.restart();
      }
    },


    []() {

      HTTPUpload& upload =
        server.upload();


      if (
        upload.status ==
        UPLOAD_FILE_START
      ) {

        if (
          !Update.begin(
            UPDATE_SIZE_UNKNOWN
          )
        ) {

          Update.printError(
            Serial
          );
        }
      }


      else if (
        upload.status ==
        UPLOAD_FILE_WRITE
      ) {

        if (
          Update.write(
            upload.buf,
            upload.currentSize
          )
          !=
          upload.currentSize
        ) {

          Update.printError(
            Serial
          );
        }
      }


      else if (
        upload.status ==
        UPLOAD_FILE_END
      ) {

        if (!Update.end(true)) {

          Update.printError(
            Serial
          );
        }
      }
    }
  );


  server.begin();
}


// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  strip.begin();

  strip.setBrightness(
    brightness
  );

  strip.clear();
  strip.show();


  WiFi.mode(WIFI_STA);

  WiFi.begin(
    ssid,
    password
  );


  while (
    WiFi.status() !=
    WL_CONNECTED
  ) {

    delay(500);
  }


  Serial.print(
    "IP Address: "
  );

  Serial.println(
    WiFi.localIP()
  );


  setupWebServer();


  // Start purple
  setSolid(
    128,
    0,
    255
  );
}


// =====================================================
// LOOP
// =====================================================

void loop() {

  server.handleClient();

  updateEffects();
}
